(()=>{
'use strict';const $=s=>document.querySelector(s),core=window.TriangleLesson,num=window.LinearLesson;
function math(host,tex){const e=document.createElement('span');e.dataset.tex=tex;host.replaceChildren(e);}
function decimal(v){return(Math.abs(v)<1e-10?0:v).toFixed(3).replace('.','{,}');}
function position(id,p){$('#'+id).style.left=(p.x/520*100)+'%';$('#'+id).style.top=(p.y/340*100)+'%';}
for(const [id,tex]of [['side-a','a'],['side-b','b'],['side-c','c']])math($('#'+id),tex);
function draw(){const b=Number($('#tri-b').value),c=Number($('#tri-c').value),A=Number($('#tri-angle').value),t=core.sas(b,c,A),p=core.layout(t);$('#b-output').value=b;$('#c-output').value=c;$('#angle-output').value=A+'°';$('#triangle-shape').setAttribute('d',`M${p.A.x} ${p.A.y}L${p.B.x} ${p.B.y}L${p.C.x} ${p.C.y}Z`);$('#triangle-height').setAttribute('d',`M${p.C.x} ${p.C.y}L${p.foot.x} ${p.foot.y}`);$('#triangle-extension').setAttribute('d',`M${Math.min(p.A.x,p.B.x,p.foot.x)} ${p.foot.y}H${Math.max(p.A.x,p.B.x,p.foot.x)}`);$('#triangle-square').setAttribute('d',`M${p.foot.x+8} ${p.foot.y}V${p.foot.y-8}H${p.foot.x}`);const anglePoints=Array.from({length:31},(_,i)=>{const r=A*Math.PI/180*i/30;return `${i?'L':'M'}${p.A.x+23*Math.cos(r)} ${p.A.y-23*Math.sin(r)}`;}).join(' ');$('#triangle-angle').setAttribute('d',anglePoints);position('vertex-a',{x:p.A.x-13,y:p.A.y+18});position('vertex-b',{x:p.B.x+13,y:p.B.y+18});position('vertex-c',{x:p.C.x,y:p.C.y-18});position('side-a',{x:(p.B.x+p.C.x)/2+17,y:(p.B.y+p.C.y)/2});position('side-b',{x:(p.A.x+p.C.x)/2-17,y:(p.A.y+p.C.y)/2});position('side-c',{x:(p.A.x+p.B.x)/2,y:p.A.y+30});math($('#triangle-equation'),String.raw`\begin{aligned}a^2&=${b}^2+${c}^2-2(${b})(${c})\cos${A}^\circ\\a&\approx${decimal(t.a)}\text{ satuan}\end{aligned}`);math($('#triangle-results'),String.raw`\begin{aligned}b&=${b},\quad c=${c}\text{ satuan}\\A&=${A}^\circ,\quad B\approx${decimal(t.B)}^\circ\\C&\approx${decimal(t.C)}^\circ\\h&=b\sin A\approx${decimal(t.height)}\text{ satuan}\\L&=\tfrac12bc\sin A\approx${decimal(t.area)}\text{ satuan luas}\end{aligned}`);const outside=t.x< -1e-10||t.x>c+1e-10;$('#triangle-note').textContent=(outside?'Kaki tinggi jatuh di luar ruas alas; perpanjangan alas membantu menunjukkan tinggi tegak lurus.':'Kaki tinggi berada pada ruas alas atau di ujungnya.')+' Untuk dua sisi tetap, sisi di depan sudut apit membesar ketika sudut dibesarkan. Luas maksimum terjadi pada sudut apit sembilan puluh derajat. Angka desimal dibulatkan menjadi tiga angka di belakang koma.';$('#triangle-plot').setAttribute('aria-label',`Segitiga ABC. Sisi b ${b}, sisi c ${c}, sudut apit A ${A} derajat. Sisi a sekitar ${t.a.toFixed(3)}. Sudut B sekitar ${t.B.toFixed(3)} dan C sekitar ${t.C.toFixed(3)} derajat. Tinggi sekitar ${t.height.toFixed(3)}. Luas sekitar ${t.area.toFixed(3)}. ${outside?'Kaki tinggi berada di luar ruas alas.':'Kaki tinggi berada pada ruas alas.'}`);}
for(const id of ['tri-b','tri-c','tri-angle'])$('#'+id).addEventListener('input',draw);const presets={initial:[5,7,60],right:[5,7,90],obtuse:[5,7,120]};document.querySelectorAll('[data-triangle]').forEach(e=>e.addEventListener('click',()=>{const [b,c,A]=presets[e.dataset.triangle];$('#tri-b').value=b;$('#tri-c').value=c;$('#tri-angle').value=A;draw();}));draw();
const questions=[{tex:String.raw`h=10\sin30^\circ`,prompt:'Tangga sepuluh meter membentuk sudut tiga puluh derajat dengan lantai. Berapa tinggi yang dicapai, dalam meter?',n:5,d:1,hint:'Sinus tiga puluh derajat adalah setengah.',why:'Sisi depan adalah sepuluh kali setengah, yaitu lima meter.'},{tex:String.raw`b=5,\quad c=7,\quad A=60^\circ`,prompt:'Berapa kuadrat panjang sisi a?',n:39,d:1,hint:'Gunakan a kuadrat sama dengan b kuadrat ditambah c kuadrat dikurangi dua b c kosinus A.',why:'Dua puluh lima ditambah empat puluh sembilan dikurangi tiga puluh lima menghasilkan tiga puluh sembilan.'},{tex:String.raw`b=6,\quad c=4,\quad A=30^\circ`,prompt:'Berapa luas segitiga, dalam satuan luas?',n:6,d:1,hint:'Luas adalah setengah dikali dua sisi dikali sinus sudut apit.',why:'Setengah dikali enam dikali empat dikali setengah menghasilkan enam satuan luas.'}];const solved=new Set();function report(i,ok,text){const e=$('#feedback'+i);e.className='feedback '+(ok?'correct':'incorrect');e.textContent=text;if(ok)solved.add(i);$('#progress').textContent=`${solved.size} dari 6 latihan sudah dijawab tepat.`;}
$('#questions').innerHTML=questions.map((q,i)=>`<div class="question"><h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><p>${q.prompt}</p><form data-question="${i}"><label for="answer${i}">Jawabanmu</label><div class="answer-line"><input id="answer${i}" type="text" required autocomplete="off" aria-describedby="feedback${i}"><button class="button" type="submit">Periksa jawaban</button></div></form><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.hint}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('form[data-question]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const i=Number(form.dataset.question),q=questions[i],a=num.parseAnswer($('#answer'+i).value),ok=num.equalAnswer(a,num.rational(q.n,q.d));report(i,ok,ok?'Tepat. '+q.why:!a?'Tulis bilangan yang diminta tanpa satuan, misalnya 5 atau 39.':'Belum tepat. Periksa sisi yang berhadapan, sudut apit, dan ukuran yang diminta.');}));
const choices=[{tex:String.raw`a=BC,\ b=CA,\ c=AB`,prompt:'Manakah pasangan yang benar dalam aturan sinus?',options:[{tex:String.raw`a/\sin B=b/\sin A`,label:'Sisi a dengan sinus B, sisi b dengan sinus A'},{tex:String.raw`a/\sin A=b/\sin B`,label:'Sisi a dengan sinus A, sisi b dengan sinus B'},{tex:String.raw`a\sin A=b\sin B`,label:'Sisi a dikali sinus A sama dengan sisi b dikali sinus B'}],answer:1,why:'Setiap sisi dipasangkan dengan sinus sudut di depannya: a dengan A, b dengan B.'},{tex:String.raw`A=30^\circ,\quad a=7,\quad b=10`,prompt:'Aturan sinus memberi sinus B sama dengan lima per tujuh. Berapa segitiga yang memenuhi data ini?',options:[{text:'Dua, karena kedua kandidat sudut B menyisakan sudut C positif.'},{text:'Satu, karena arcsin hanya memberikan satu sudut utama.'},{text:'Tidak ada, karena sudut B tidak istimewa.'}],answer:0,why:'Kandidat B sekitar empat puluh lima koma lima delapan lima derajat dan seratus tiga puluh empat koma empat satu lima derajat. Keduanya membuat jumlah A dan B kurang dari seratus delapan puluh derajat.'},{tex:String.raw`b,c\text{ tetap},\quad0^\circ<A<180^\circ`,prompt:'Apa yang terjadi ketika sudut apit A membesar melewati sembilan puluh derajat?',options:[{text:'Sisi a dan luas keduanya selalu mengecil.'},{text:'Sisi a dan luas keduanya selalu membesar.'},{text:'Sisi a membesar, tetapi luas mengecil.'}],answer:2,why:'Aturan kosinus membuat sisi a terus membesar saat kosinus A menurun. Namun luas mengikuti sinus A, yang menurun setelah sembilan puluh derajat.'}];for(let j=0;j<choices.length;j++){const i=j+3,q=choices[j],box=document.createElement('div');box.className='question';box.innerHTML=`<h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><fieldset><legend>${q.prompt}</legend>${q.options.map((o,k)=>`<label class="choice"><input type="radio" name="choice${i}" value="${k}" ${o.label?'aria-label="'+o.label+'"':''}>${o.tex?'<span data-tex="'+o.tex+'"></span>':o.text}</label>`).join('')}</fieldset><button type="button" class="button" data-check="${i}">Periksa jawaban</button><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details>`;$('#questions').append(box);box.querySelector('button').addEventListener('click',()=>{const a=$(`[name="choice${i}"]:checked`),ok=!!a&&Number(a.value)===q.answer;report(i,ok,!a?'Pilih jawaban dahulu.':(ok?'Tepat. ':'Belum tepat. ')+q.why);});}
const storage={get(k){try{return localStorage.getItem('fondasi-triangle-apps-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-triangle-apps-'+k,v);return true}catch{return false}}};$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#save-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan di peramban ini.':'Catatan belum dapat disimpan; salin jika diperlukan.';});function complete(saved){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#complete-note').textContent=saved?'Kemajuan tersimpan di peramban ini. Kamu bisa mencoba kembali kapan saja.':'Bacaan selesai; kemajuan belum dapat disimpan di peramban ini.';}$('#complete').addEventListener('click',()=>complete(storage.set('complete','yes')));if(storage.get('complete')==='yes')complete(true);
})();